<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { Boxes, Ship, CircleCheck, CircleAlert, Plus, ArrowRight, ArrowUpRight, ChevronRight, RefreshCw, LoaderCircle, Clock3, Globe2, Package, Truck, Building2, ShieldCheck } from 'lucide-vue-next';
import { useAuth } from '../composables/useAuth.js';
import { overviewApi, attentionReason, distributionSegments, overviewCopy } from '../services/overview-api.js';
import { trackingStatusName } from '../services/container-tracking.js';
import { journeyStatus } from '../services/tracking-directory.js';
const emit=defineEmits(['register','tracking','journey','shipper']);const {session,request}=useAuth();const api=overviewApi(request);
const isAdmin=computed(()=>session.value?.user.userType===1);const isShipper=computed(()=>session.value?.user.userType===3);const isConsignee=computed(()=>session.value?.user.userType===2);const copy=computed(()=>overviewCopy(session.value?.user.userType));
const data=ref(null);const loading=ref(false);const error=ref('');let disposed=false;
const colors={'1':'#9fb4c5','2':'#839cd2','3':'#219ac6','4':'#46a7a3','5':'#9a86bc','6':'#49a58d',hold:'#d5a14e',cancelled:'#c7d0d8'};
const stages=computed(()=>(data.value?.stages||[]).filter(stage=>stage.count>0).map(stage=>({...stage,name:stage.key==='hold'?'On hold':stage.key==='cancelled'?'Cancelled':trackingStatusName(Number(stage.key)),color:colors[stage.key]})));
const donut=computed(()=>distributionSegments(stages.value,data.value?.counts.total||0));
function count(value){return Number(value||0).toLocaleString();}
function date(value){return value?new Date(value+'T00:00:00').toLocaleDateString(undefined,{day:'2-digit',month:'short',year:'numeric'}):'-';}
function time(value){return value?new Date(value).toLocaleString(undefined,{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'-';}
function overdue(item){return item.status===1&&item.trackingStatus!==6&&item.expectedArrival<data.value.businessDate;}
async function load(){if(loading.value)return;loading.value=true;error.value='';try{const result=await api.get();if(!disposed)data.value=result;}catch(failure){if(!disposed)error.value=failure.message;}finally{if(!disposed)loading.value=false;}}
onMounted(load);onBeforeUnmount(()=>{disposed=true;});
</script>
<template>
  <section class="admin-overview" aria-labelledby="admin-overview-title" :aria-busy="loading">
    <div class="page-heading admin-overview-heading"><div><p class="eyebrow">YOUR OPERATIONS, AT A GLANCE</p><h1 id="admin-overview-title">{{ copy.title }}</h1><p>{{ copy.description }}</p></div><button v-if="isAdmin || data?.profile.canRegister" type="button" class="btn primary" @click="emit('register')"><Plus :size="17" />Register container</button></div>
    <div class="overview-refresh-row"><span><Clock3 :size="13" />{{ data ? 'Updated '+time(data.generatedAt) : 'Your operations overview' }}</span><button type="button" class="text-btn" @click="load" :disabled="loading"><RefreshCw :size="14" :class="{spin:loading}" />{{ loading ? 'Refreshing...' : 'Refresh overview' }}</button></div>
    <div v-if="error" class="form-error" role="alert">{{ error }} <button type="button" class="text-btn" @click="load" :disabled="loading">Try again</button></div>
    <div v-if="loading && !data" class="overview-loading" role="status"><LoaderCircle class="spin" :size="26" /><p>Loading your operations...</p></div>
    <template v-if="data">
      <section v-if="!isAdmin" class="overview-account-strip" aria-label="Your company workspace"><span class="overview-company-icon"><Truck v-if="isShipper" :size="23" /><Building2 v-else :size="23" /></span><div><small>{{ copy.role }}</small><strong>{{ data.profile.companyName }}</strong><p>{{ data.profile.code }}<span v-if="isShipper"> &middot; {{ data.profile.consigneeName ? 'Consignee: '+data.profile.consigneeName : 'No consignee linked' }}</span></p></div><span class="overview-scope-tag"><ShieldCheck :size="14" />{{ isShipper ? 'Your shipments' : 'Your connected network' }}</span></section>
      <p v-if="isShipper && !data.profile.canRegister" class="overview-partner-notice">New registrations are unavailable for this account. Your existing shipment tracking remains accessible.</p>
      <div class="overview-metrics">
        <button type="button" class="panel overview-metric" @click="emit('tracking','')"><span class="overview-metric-label">Total containers<span class="overview-metric-icon teal"><Boxes :size="20" /></span></span><strong>{{ count(data.counts.total) }}</strong><small>{{ count(data.counts.active) }} active registrations &middot; {{ count(data.counts.cancelled) }} cancelled</small></button>
        <button type="button" class="panel overview-metric" @click="emit('tracking','3')"><span class="overview-metric-label">In transit<span class="overview-metric-icon blue"><Ship :size="20" /></span></span><strong>{{ count(data.counts.inTransit) }}</strong><small>Latest reported stage &middot; including held shipments</small></button>
        <button type="button" class="panel overview-metric" @click="emit('tracking','6')"><span class="overview-metric-label">Delivered<span class="overview-metric-icon green"><CircleCheck :size="20" /></span></span><strong>{{ count(data.counts.delivered) }}</strong><small>Delivery recorded by operations</small></button>
        <button type="button" class="panel overview-metric" @click="emit('tracking','hold')"><span class="overview-metric-label">On hold<span class="overview-metric-icon amber"><CircleAlert :size="20" /></span></span><strong>{{ count(data.counts.onHold) }}</strong><small><span class="overview-warning-text">{{ count(data.counts.overdue) }} overdue arrivals</span> across open journeys</small></button>
      </div>
      <div class="overview-middle-grid">
        <section class="overview-network"><svg class="overview-world-art" viewBox="0 0 800 270" aria-hidden="true"><defs><pattern id="overview-map-dots" x="0" y="0" width="8" height="8" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1.2" fill="currentColor" /></pattern></defs><path d="M67 57L116 25 159 30 188 50 218 45 237 73 210 102 181 111 178 137 149 124 120 94 82 90ZM189 144L226 157 246 193 232 231 214 257 200 209 178 178ZM350 53L381 40 412 52 445 34 495 39 527 26 592 38 646 65 701 76 720 103 692 129 653 113 626 123 607 106 573 126 547 117 529 146 506 130 488 158 469 132 452 104 424 102 407 85 377 88 363 70ZM377 108L411 103 445 123 452 154 429 190 409 219 389 195 377 160 355 129ZM561 163L595 169 623 181 646 185 654 199 619 194 591 184ZM657 208L682 194 717 202 739 225 724 247 682 252 659 230Z" fill="url(#overview-map-dots)" /></svg>
          <div class="overview-network-heading"><div><p class="eyebrow">BEYOND BORDERS</p><h2>Your world, in motion.</h2><p>{{ count(data.counts.routes) }} shipping routes. One connected workspace.</p></div><span><Globe2 :size="16" />{{ count(data.counts.countries) }} countries</span></div>
          <div v-if="data.routes.length" class="overview-route-list"><div v-for="route in data.routes" :key="route.originPortId+'-'+route.destinationPortId"><span>{{ route.origin }}</span><ArrowRight :size="15" /><span>{{ route.destination }}</span><strong>{{ count(route.containers) }}<small>containers</small></strong></div></div><p v-else class="overview-network-empty">Your registered shipping routes will appear here.</p>
          <div class="overview-network-footer"><span><Ship :size="15" />Routes from your registered shipments</span><button type="button" @click="emit('tracking','')">Explore tracking <ArrowUpRight :size="16" /></button></div>
        </section>
        <section class="panel overview-distribution"><div class="overview-panel-heading"><div><h2>Shipment overview</h2><p>{{ copy.shipmentDescription }}</p></div><Boxes :size="19" /></div><div class="overview-distribution-body"><div class="overview-donut" :style="{background:donut}" role="img" :aria-label="stages.length ? stages.map(stage=>stage.name+': '+stage.count).join(', ') : 'No container registrations'"><div><strong>{{ count(data.counts.total) }}</strong><span>containers</span></div></div><ul class="overview-stage-legend"><li v-for="stage in stages" :key="stage.key"><span :style="{background:stage.color}"></span><span>{{ stage.name }}</span><strong>{{ count(stage.count) }}</strong></li><li v-if="!stages.length" class="overview-no-stages">No registrations yet</li></ul></div><div class="overview-distribution-note"><Clock3 :size="14" />Based on the latest recorded status</div></section>
      </div>
      <div v-if="isAdmin" class="overview-partner-strip"><span><Truck :size="17" /><strong>{{ count(data.counts.shippers) }}</strong> active shippers</span><span><Package :size="17" /><strong>{{ count(data.counts.consignees) }}</strong> active consignees</span><span><ShieldCheck :size="15" />Connected through Kodiak operations</span></div>
      <section v-else-if="isConsignee" class="panel overview-supplier-network" aria-labelledby="supplier-network-title"><div class="overview-panel-heading"><div><h2 id="supplier-network-title">Your shipper network <span class="count-pill">{{ count(data.partnerCount) }}</span></h2><p>Companies currently linked to your consignee account</p></div><Truck :size="20" /></div><div v-if="data.partners.length" class="overview-network-partners"><button v-for="partner in data.partners" :key="partner.id" type="button" @click="emit('shipper',partner.id)"><span class="overview-network-partner-icon"><Truck :size="19" /></span><span><strong>{{ partner.name }}</strong><small>{{ partner.code }} &middot; {{ count(partner.containers) }} {{ partner.containers === 1 ? 'registration' : 'registrations' }}</small></span><span class="badge" :class="partner.status===1 ? 'green' : 'red'">{{ partner.status===1 ? 'Active' : 'Blacklisted' }}</span><ChevronRight :size="16" /></button></div><p v-else class="overview-empty-cell">No shippers are currently linked to your account. Kodiak operations can help connect your suppliers.</p><p v-if="data.partnerCount>data.partners.length" class="overview-network-count">Showing {{ data.partners.length }} of {{ data.partnerCount }} linked shippers. Use the shipper filter in Tracking to explore the full network.</p></section>
      <div v-else class="overview-partner-strip"><span><Building2 :size="17" />{{ data.profile.consigneeName || 'Consignee link pending' }}</span><span><ShieldCheck :size="15" />Kodiak operations maintains tracking updates</span></div>
      <section class="panel overview-recent"><div class="overview-panel-heading"><div><h2>Recent containers</h2><p>{{ copy.recentDescription }}</p></div><button type="button" class="text-btn" @click="emit('tracking','')">View all containers <ArrowRight :size="15" /></button></div><div class="overview-table-wrap"><table class="overview-table"><caption class="sr-only">Recent container registrations</caption><thead><tr><th>Container / booking</th><th>Route</th><th>Shipper</th><th>Status</th><th>Expected arrival</th><th><span class="sr-only">Open journey</span></th></tr></thead><tbody><tr v-for="item in data.recent" :key="item.id"><td><button type="button" class="overview-container-link" @click="emit('journey',item.id)"><span><Package :size="18" /></span><span><strong>{{ item.containerNumber || 'Pending allocation' }}</strong><small>{{ item.code }}</small></span></button></td><td><span class="overview-table-route">{{ item.origin }}<ArrowRight :size="12" />{{ item.destination }}</span></td><td>{{ item.shipperName }}</td><td><span class="badge" :class="journeyStatus(item).tone">{{ journeyStatus(item).name }}</span></td><td><strong :class="{'overview-overdue':overdue(item)}">{{ date(item.expectedArrival) }}</strong><small v-if="overdue(item)" class="overview-overdue">Arrival date passed</small></td><td><button type="button" class="icon-btn" @click="emit('journey',item.id)" :aria-label="'Open '+item.code"><ArrowUpRight :size="18" /></button></td></tr><tr v-if="!data.recent.length"><td colspan="6" class="overview-empty-cell">No containers yet. Register your first shipment to get started.</td></tr></tbody></table></div></section>
      <div class="overview-bottom-grid"><section class="panel overview-activity"><div class="overview-panel-heading"><div><h2>Activity feed</h2><p>The latest recorded changes in your operations</p></div><Clock3 :size="19" /></div><button v-for="(entry,index) in data.activity" :key="index" type="button" class="overview-activity-row" @click="emit('journey',entry.containerId)"><span class="overview-activity-icon"><Ship v-if="entry.kind==='tracking'" :size="17" /><Package v-else :size="17" /></span><span><strong>{{ entry.code }} <span>{{ entry.kind==='registration' ? 'Registered' : trackingStatusName(entry.status) }}</span></strong><small>{{ entry.location }} &middot; {{ time(entry.recordedAt) }}</small></span><ChevronRight :size="16" /></button><p v-if="!data.activity.length" class="overview-empty-cell">Your registration and tracking updates will appear here.</p></section>
        <section class="panel overview-attention"><div class="overview-panel-heading"><div><h2>Needs attention <span class="count-pill amber">{{ count(data.counts.attention) }}</span></h2><p>Prioritize holds, overdue arrivals, and allocation</p></div><CircleAlert :size="20" /></div><button v-for="item in data.attention" :key="item.id" type="button" class="overview-attention-row" @click="emit('journey',item.id)"><span class="overview-attention-dot"></span><span><strong>{{ item.code }} &middot; {{ attentionReason(item,data.businessDate).title }}</strong><small>{{ isAdmin ? attentionReason(item,data.businessDate).description : item.isOnHold ? 'Contact Kodiak operations for a hold review.' : item.expectedArrival < data.businessDate ? 'Ask Kodiak for the latest location and arrival estimate.' : 'A physical container number is awaiting allocation.' }}</small></span><ChevronRight :size="16" /></button><div v-if="!data.attention.length" class="overview-clear-state"><CircleCheck :size="29" /><h3>Everything is on course</h3><p>No holds, overdue arrivals, or pending container allocations.</p></div></section>
      </div>
    </template>
  </section>
</template>
